+            final Cluster.ClusterNode clusterNode = cluster.getAnyNode();
+            logger.debug("rebooting [{}]", clusterNode.getId());
+            clusterNode.close();
+            cluster.clusterNodes.forEach(cn -> cluster.deterministicTaskQueue.scheduleNow(cn.onNode(new Runnable() {
+                @Override
+                public void run() {
