+                }
+
+                @Override
+                public String toString() {
+                    return "disconnect from " + clusterNode.getLocalNode() + " after shutdown";
+                }
+            })));
+            IllegalStateException ise = expectThrows(
+                IllegalStateException.class,
+                () -> cluster.clusterNodes.replaceAll(
+                    cn -> cn == clusterNode
+                        ? cn.restartedNode(
+                            Function.identity(),
+                            Function.identity(),
+                            Settings.builder()
