+            final Cluster.ClusterNode disconnect2 = cluster.getAnyNodeExcept(disconnect1);
+            logger.info("--> disconnecting {} and {}", disconnect1, disconnect2);
+            disconnect1.disconnect();
+            disconnect2.disconnect();
+            cluster.stabilise();
+
+            {
