+            return TimeValue.timeValueDays(1);
+        }
+        if (retention.compareTo(TimeValue.timeValueDays(90)) <= 0) {
+            return TimeValue.timeValueDays(7);
+        }
+        return TimeValue.timeValueDays(30);
+    }
+
+    /**
