+
+[source,console-result]
+----
+{
+    "size": 10,
+    "from": 0,
+    "query": {
+        "multi_match": {
+            "query": "my first query",
+            "fields": [
+                "title^10",
+                "text^1"
+            ]
+        }
+    }
+}
+
+----
+
